import{_ as s,o as i,c as e,a5 as n}from"./chunks/framework.bIR-4glx.js";const E=JSON.parse('{"title":"读者实践回执：七天后，还留下了什么","description":"用私密优先的两次记录，把阅读入口、实际行动、即时结果、延迟保持、迁移失败和书稿反馈放在同一页，再决定是否公开分享。","frontmatter":{"title":"读者实践回执：七天后，还留下了什么","description":"用私密优先的两次记录，把阅读入口、实际行动、即时结果、延迟保持、迁移失败和书稿反馈放在同一页，再决定是否公开分享。","updated":"2026-09-02T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/reader-field-note.zh.md","name":"reader-field-note.zh.md"}},"headers":[],"relativePath":"templates/reader-field-note.md","filePath":"templates/reader-field-note.md","lastUpdated":1788307200000}'),t={name:"templates/reader-field-note.md"};function l(p,a,h,d,r,o){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="读者实践回执-七天后-还留下了什么" tabindex="-1">读者实践回执：七天后，还留下了什么 <a class="header-anchor" href="#读者实践回执-七天后-还留下了什么" aria-label="Permalink to &quot;读者实践回执：七天后，还留下了什么&quot;">​</a></h1><p>这张回执不是书评，也不是要求你证明一本书有效。它只追踪一条更朴素的路径：<strong>你因为什么问题进入，读完后做了什么，几天以后还留下什么。</strong></p><p>请先复制到自己的私有笔记。第一次在阅读后十分钟填写，第二次在三到七天后填写。不要为了完成表格反复重读原文；第二次记录的价值，正来自提示已经变少。</p><p>公开分享始终是可选项。没有得到授权的姓名、公司、客户、关系、健康、财务和会话内容，不应为了“证明真实”进入公开回执。</p><h2 id="先在私下完成" tabindex="-1">先在私下完成 <a class="header-anchor" href="#先在私下完成" aria-label="Permalink to &quot;先在私下完成&quot;">​</a></h2><p>一份有用的回执只需要回答四件事：</p><ol><li>我原来面对的真实问题是什么？</li><li>我实际做出了什么，而不是只同意了什么？</li><li>三到七天后，我能否在提示减少或条件变化时再做一次？</li><li>哪一段帮助了行动，哪一段仍然抽象、越界或无法使用？</li></ol><p>没有行动、没有复测，也可以如实填写。“暂时只产生认同感”本身就是证据，不需要补写一个成功故事。</p><h2 id="第一次填写-阅读后十分钟" tabindex="-1">第一次填写：阅读后十分钟 <a class="header-anchor" href="#第一次填写-阅读后十分钟" aria-label="Permalink to &quot;第一次填写：阅读后十分钟&quot;">​</a></h2><h3 id="_1-进入问题" tabindex="-1">1. 进入问题 <a class="header-anchor" href="#_1-进入问题" aria-label="Permalink to &quot;1. 进入问题&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">章节或页面：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我为什么打开它：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">当时的真实场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">阅读前已经会什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">阅读前卡在哪里：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">今天可用的时间与容量：</span></span></code></pre></div><p>不要写“我想变优秀”。写一个能够发生的场景，例如：“我需要把项目风险交接给同事，但现有记录只有聊天和零散截图。”</p><h3 id="_2-用自己的话复述" tabindex="-1">2. 用自己的话复述 <a class="header-anchor" href="#_2-用自己的话复述" aria-label="Permalink to &quot;2. 用自己的话复述&quot;">​</a></h3><p>合上页面，用不超过三句话写：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我理解的核心判断：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">它依据的事实、例子或来源：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">它仍然不能替我证明什么：</span></span></code></pre></div><p>如果只能复制原句，先不要急着评价好坏。写下“我还不能用自己的话说明”，这会比一段漂亮摘抄更准确。</p><h3 id="_3-做一个最小行动" tabindex="-1">3. 做一个最小行动 <a class="header-anchor" href="#_3-做一个最小行动" aria-label="Permalink to &quot;3. 做一个最小行动&quot;">​</a></h3><p>选择一个 10–45 分钟可以结束的动作。动作必须留下可查看的痕迹。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我要完成的最小动作：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">完成标准：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">是否使用 AI / 他人帮助：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我必须自己决定的部分：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">作品、录音、代码或记录位置：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">停止条件：</span></span></code></pre></div><p>可用动作包括：重写一封邮件、录一段说明、修复一个测试、建立一页学习状态、删除一项无效要求，或向一个受影响的人确认边界。继续收藏资料不算行动。</p><h3 id="_4-保存即时结果" tabindex="-1">4. 保存即时结果 <a class="header-anchor" href="#_4-保存即时结果" aria-label="Permalink to &quot;4. 保存即时结果&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">实际完成了什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">没有完成什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">收到的直接反馈或结果：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最大错误 / 阻力：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">现在最容易夸大的结论：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次复测日期：</span></span></code></pre></div><p>即时顺利只能说明这一次在当前条件下发生了什么。若使用 AI，请把辅助版和关闭 AI 后的独立版分开保存。</p><h2 id="第二次填写-三到七天后" tabindex="-1">第二次填写：三到七天后 <a class="header-anchor" href="#第二次填写-三到七天后" aria-label="Permalink to &quot;第二次填写：三到七天后&quot;">​</a></h2><h3 id="_5-不重读-先复测" tabindex="-1">5. 不重读，先复测 <a class="header-anchor" href="#_5-不重读-先复测" aria-label="Permalink to &quot;5. 不重读，先复测&quot;">​</a></h3><p>先不要打开原章节、聊天记录或答案。完成一个相近任务，再填写：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">复测日期与间隔：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">撤掉了哪些提示：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">相近任务：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我独立完成了什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我仍然需要什么提示：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">与第一次相比，真正留下了什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">证据位置：</span></span></code></pre></div><p>如果完全记不起来，也不要把失败改成“最近太忙”。先记录事实，再决定任务是否过大、入口是否不清，或内容只制造了短期认同。</p><h3 id="_6-换一个条件" tabindex="-1">6. 换一个条件 <a class="header-anchor" href="#_6-换一个条件" aria-label="Permalink to &quot;6. 换一个条件&quot;">​</a></h3><p>迁移只改变一个条件即可：主题、受众、时间限制、材料、工具权限或任务目的。</p><table tabindex="0"><thead><tr><th>改变的条件</th><th>新任务</th><th>独立结果</th><th>失败在哪里</th><th>下一步</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>迁移失败不是差评。它能指出一个方法的适用边界，也能帮助作者区分“句子听起来正确”和“读者真的能够使用”。</p><h3 id="_7-写出对书稿的反馈" tabindex="-1">7. 写出对书稿的反馈 <a class="header-anchor" href="#_7-写出对书稿的反馈" aria-label="Permalink to &quot;7. 写出对书稿的反馈&quot;">​</a></h3><p>请尽量指向具体段落、标题、例子或工具：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最帮助我行动的一处：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">仍然抽象或不知道怎样使用的一处：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">缺少的边界、例子或前置条件：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">可以删除或缩短的一处：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我尝试后没有奏效的部分：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我希望下一版回答的问题：</span></span></code></pre></div><p>“写得很好”让作者开心，却很难改变下一版。“我按第三步做了，但不知道完成标准怎么写”更有编辑价值。</p><h2 id="把事实、解释和愿望分开" tabindex="-1">把事实、解释和愿望分开 <a class="header-anchor" href="#把事实、解释和愿望分开" aria-label="Permalink to &quot;把事实、解释和愿望分开&quot;">​</a></h2><p>分享前，检查三层是否混在一起：</p><table tabindex="0"><thead><tr><th>层</th><th>示例</th></tr></thead><tbody><tr><td>事实</td><td>我在七天后没有看原文，完成了两项要求，第三项需要提示</td></tr><tr><td>解释</td><td>可能因为示例让我记住了结构，但边界部分仍然抽象</td></tr><tr><td>愿望</td><td>我希望下一版增加一个完整填写样例</td></tr></tbody></table><p>不要把一次个人结果写成“所有人都会有效”，也不要把一次失败写成“这个方法完全无用”。保留任务、条件和样本，结论才有边界。</p><h2 id="分享前的隐私门" tabindex="-1">分享前的隐私门 <a class="header-anchor" href="#分享前的隐私门" aria-label="Permalink to &quot;分享前的隐私门&quot;">​</a></h2><p>只有全部通过，才考虑公开：</p><ul><li>[ ] 已删除密码、密钥、证件、精确地址和私人联系方式；</li><li>[ ] 已删除客户数据、公司机密、医疗记录和未公开财务信息；</li><li>[ ] 已删除不必要的第三方姓名、照片、关系与可识别细节；</li><li>[ ] 涉及他人的内容已经获得授权，或改写为不可识别的最少事实；</li><li>[ ] 已区分直接观察、个人解释与下一步假设；</li><li>[ ] 我接受这份记录可能长期公开并被搜索。</li></ul><p>若任何一项不能确认，就保留在私有笔记。作者不需要通过获得你的隐私来改进一本书。</p><h2 id="什么时候转入证据链" tabindex="-1">什么时候转入证据链 <a class="header-anchor" href="#什么时候转入证据链" aria-label="Permalink to &quot;什么时候转入证据链&quot;">​</a></h2><p>读者回执适合回答“这一次阅读有没有进入行动”。当同一能力需要比较多个样本、评分条件、延迟保持和跨场景迁移时，把记录转入<a href="./evidence-chain">证据链模板</a>。</p><p>如果你需要看一份完整填写过程，先读<a href="./toolkit-walkthrough">工具箱实战：让 AI 跨会话继续一项 90 天学习</a>。它使用合成数据演示如何把学习状态、AI 任务、作品、复测和这张回执串起来。</p><p>完成隐私检查后，可以选择提交<a href="https://github.com/byoungd/up/issues/new?template=reader-field-note.yml" target="_blank" rel="noreferrer">公开读者回执</a>。公开与否不会改变这次实践的价值。</p><p>相关入口：<a href="./../threads/part-5/book-as-proof">案例篇：让这本书证明它的方法</a> ｜ <a href="./toolkit">工具箱总览</a> ｜ <a href="./weekly-review">每周复盘</a></p>`,49)])])}const c=s(t,[["render",l]]);export{E as __pageData,c as default};
